-- Medicine CVS Anatomy & Physiology Flashcards (FC 1-100)
-- Source: Guyton & Hall Medical Physiology 14th Ed; BRS Physiology 6th Ed
-- Topic: Cardiovascular System | Category: Anatomy & Physiology

INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES

('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','easy','flashcard','What are intercalated discs and what is their function in cardiac muscle?','["Specialised junctions between cardiac myocytes containing gap junctions (electrical coupling) and desmosomes (mechanical coupling); allow action potentials to spread rapidly making the heart a functional syncytium."]','A','Gap junctions contain connexin-43; desmosomes prevent cells from pulling apart. High-yield: explains why the whole ventricle contracts as one unit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','easy','flashcard','Which phase of the cardiac action potential is sustained by L-type calcium channel opening?','["Phase 2 (the plateau phase). L-type Ca2+ channels open and maintain depolarisation for 200-300 ms, allowing complete ventricular contraction."]','A','Remember: Phase 0 = fast Na+; Phase 1 = transient K+ out; Phase 2 = Ca2+ in (plateau); Phase 3 = K+ out (repolarisation); Phase 4 = resting potential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','medium','flashcard','What ion and channel type primarily sets the resting membrane potential of ventricular myocytes at -90 mV?','["Potassium (K+) via inwardly rectifying K+ channels (IK1). High resting K+ conductance allows K+ efflux, creating a negative interior."]','A','This -90 mV potential is more negative than SA node (~-60 mV), which is why fast Na+ channels are available in ventricular cells but inactivated in the SA node.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','easy','flashcard','Why can cardiac muscle NOT undergo tetanus, unlike skeletal muscle?','["The cardiac absolute refractory period (~200-250 ms) lasts almost as long as the contraction (~300 ms), preventing re-excitation and summation."]','A','This is physiologically vital - tetanus of the heart would stop diastolic filling and be fatal. The long refractory period is due to the prolonged plateau phase (L-type Ca2+ channels).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','medium','flashcard','What is the role of T-tubules in cardiac excitation-contraction coupling?','["T-tubules carry the action potential deep into the myocyte interior, activating L-type Ca2+ channels throughout the cell simultaneously, triggering CICR (calcium-induced calcium release) from the SR."]','A','CICR = ryanodine receptor (RyR2) opens when triggered by L-type Ca2+ channel flux; the SR releases stored Ca2+ amplifying the signal 10-50x. Cardiac T-tubules are wider than skeletal muscle T-tubules.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','medium','flashcard','Which troponin subunit binds calcium during cardiac muscle contraction, and what does this cause?','["Troponin C (TnC) binds Ca2+, causing a conformational change that moves tropomyosin away from the myosin-binding sites on actin, allowing cross-bridge attachment and force generation."]','A','Troponin complex: TnC (Ca2+ binding), TnI (inhibitory - holds tropomyosin in blocking position), TnT (binds tropomyosin). Cardiac TnI and TnT are cardiac-specific - basis for serum troponin assays in MI diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','hard','flashcard','Why does phase 0 (upstroke) of the SA node action potential differ from ventricular muscle phase 0?','["SA node phase 0 is carried by L-type Ca2+ channels (slow, graded upstroke) because the resting potential (~-60 mV) inactivates fast Na+ channels. Ventricular phase 0 is carried by fast Na+ channels (rapid upstroke, resting -90 mV)."]','A','Clinical application: verapamil and diltiazem (L-type Ca2+ blockers) slow SA node rate and AV conduction but do NOT affect fast Na+-dependent tissues (Purkinje fibres, ventricular muscle).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','medium','flashcard','What are the key structural differences between cardiac and skeletal muscle?','["Cardiac: branched cells, single nucleus, intercalated discs, involuntary, fatigue-resistant (many mitochondria). Skeletal: unbranched, multinucleated, no intercalated discs, voluntary, fatigable."]','A','Both use actin-myosin cross-bridge cycling. Key difference: cardiac cells are electrically coupled (gap junctions); skeletal each cell independently innervated by motor nerve. Cardiac cannot tetanise; skeletal can.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','hard','flashcard','What is calcium-induced calcium release (CICR) and where does it occur in cardiac myocytes?','["CICR occurs at dyads (T-tubule apposed to SR membrane). Ca2+ entry via L-type channels triggers ryanodine receptor 2 (RyR2) on the SR to release much larger amounts of stored Ca2+, producing the intracellular Ca2+ transient needed for contraction."]','A','The ratio of SR-released Ca2+ to L-type Ca2+ channel-triggered Ca2+ is approximately 10:1. Drugs that sensitise RyR2 (e.g., caffeine) increase force. SERCA2a pumps Ca2+ back into SR during relaxation (impaired in heart failure).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Muscle Structure & Action Potential','medium','flashcard','What is the function of the Na+/Ca2+ exchanger (NCX) in cardiac myocytes?','["NCX (exchanger ratio 3 Na+:1 Ca2+) extrudes Ca2+ from the cytoplasm during diastole, working alongside SERCA2a to lower intracellular Ca2+ and allow relaxation (lusitropy)."]','A','In heart failure, reduced SERCA2a activity means NCX works harder; this can cause Ca2+ overload and arrhythmias. Digoxin works by inhibiting Na+/K+-ATPase, raising intracellular Na+, reducing NCX driving force, increasing [Ca2+]i and contractility.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','easy','flashcard','List the phases of the cardiac cycle in correct sequence.','["1. Atrial systole (atrial kick) 2. Isovolumetric contraction (all valves closed, pressure rises) 3. Rapid ejection (aortic valve opens) 4. Reduced ejection 5. Isovolumetric relaxation (all valves closed) 6. Rapid ventricular filling 7. Slow filling (diastasis)"]','A','The AV valves close at the start of isovolumetric contraction (S1). The aortic valve closes at the start of isovolumetric relaxation (S2/dicrotic notch). Knowing this allows ECG-cardiac cycle correlation in OSCE stations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','easy','flashcard','What cardiac event produces the first heart sound (S1) and what cardiac event produces S2?','["S1 (\"lub\") = closure of the mitral and tricuspid valves at the start of ventricular systole. S2 (\"dub\") = closure of the aortic and pulmonary valves at the end of ventricular ejection."]','A','S1 is best heard at the apex (mitral area). S2 is best heard at the base (aortic/pulmonary area). Wide splitting of S2 on inspiration = RBBB or pulmonary stenosis. Fixed splitting = ASD. Reversed (paradoxical) splitting = LBBB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','medium','flashcard','What is the dicrotic notch on the aortic pressure waveform and what causes it?','["The dicrotic notch (incisura) is a brief pressure dip and rebound on the aortic waveform. It is caused by: (1) momentary reversal of blood flow that closes the aortic valve, (2) elastic recoil of the aortic wall. It marks the end of systole."]','A','The dicrotic notch is absent or diminished in aortic regurgitation (the valve cannot close properly). Augmentation index (related to pulse wave reflection and the dicrotic notch) increases with arterial stiffness.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','medium','flashcard','What is ejection fraction (EF) and what is the normal value?','["EF = (EDV - ESV) / EDV x 100. Normal EF is 55-70%. EF reflects systolic function (contractility)."]','A','HFrEF (heart failure with reduced EF) = EF <40%. HFpEF (preserved EF) = EF ≥50% but diastolic dysfunction. EF is measured by echocardiography or cardiac MRI. Stroke volume = EDV - ESV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','medium','flashcard','During isovolumetric contraction, what is the state of all four cardiac valves?','["All four valves are CLOSED. The ventricle is contracting (pressure rising) but has not yet generated enough pressure to open the aortic/pulmonary valves, and AV valves are already closed by rising ventricular pressure."]','A','This phase accounts for ~50 ms at rest. Energy is consumed (oxygen demand is high) but no blood is ejected. LVEDP = 5-12 mmHg. The aortic valve opens when LV pressure exceeds ~80 mmHg (aortic diastolic pressure).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','easy','flashcard','What is the "atrial kick" and why is it important?','["Atrial kick is the final 20-30% of ventricular filling contributed by active atrial contraction (atrial systole) at end-diastole."]','A','Atrial kick becomes critically important at high heart rates (when passive filling time is short) and in stiff/hypertrophied ventricles (HFpEF). Loss of atrial kick in atrial fibrillation can reduce CO by 20-30% in patients with poor ventricular compliance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','hard','flashcard','What does the "a wave" of the JVP represent, and when is it absent?','["\"a wave\" = right atrial contraction (end-diastole). Absent in atrial fibrillation (no coordinated atrial contraction)."]','A','Cannon a wave: right atrium contracts against a closed tricuspid valve (complete heart block, ventricular tachycardia). Large a wave without cannon: pulmonary hypertension, pulmonary stenosis, tricuspid stenosis. The c, x, v, y components follow in sequence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','hard','flashcard','On a PV loop, what do the four corners represent?','["Bottom-right = end-diastole (EDV); Top-right = end of isovolumetric contraction (aortic valve opens); Top-left = end-systole (ESV, aortic valve closes); Bottom-left = end of isovolumetric relaxation (mitral valve opens)."]','A','Width of loop = stroke volume. Area enclosed = stroke work (external work done by the ventricle). Increased contractility shifts the upper-left corner leftward and upward. Increased preload shifts the lower-right corner rightward.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','medium','flashcard','Why does diastole shorten proportionally more than systole as heart rate increases?','["Systole has a minimum duration determined by the time needed for the ventricle to contract, eject blood, and relax (approximately 200-250 ms). As HR increases, the extra time saved comes almost entirely from shortening diastole."]','A','At very high heart rates (e.g., 180 bpm), diastolic filling time is so short that the ventricle cannot fill adequately, reducing stroke volume. This is why tachyarrhythmias (e.g., atrial flutter at 2:1 block = 150 bpm) impair cardiac output.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','The Cardiac Cycle','medium','flashcard','What is meant by "preload" in cardiac physiology?','["Preload is the ventricular wall tension at end-diastole, proportional to end-diastolic volume (EDV). It represents the degree of myocyte stretch before contraction (sarcomere length at end-diastole)."]','A','Clinically approximated by: LVEDP (left) or CVP/RAP (right). Increases in: fluid overload, mitral regurgitation, high venous return. Decreases in: haemorrhage, dehydration, nitrates (venodilators). Frank-Starling law describes how preload increases SV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','easy','flashcard','State the Frank-Starling law of the heart.','["The heart pumps all the blood returned to it: within physiological limits, stroke volume (and cardiac output) increases as ventricular end-diastolic volume (preload) increases."]','A','Mechanism: greater EDV stretches sarcomeres toward optimal length (~2.2 µm), increasing actin-myosin overlap AND increasing Ca2+ sensitivity of troponin C. This intrinsic mechanism allows CO to match venous return without neural input.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','easy','flashcard','What is the Fick principle for measuring cardiac output?','["CO = VO2 / (CaO2 - CvO2). Where VO2 = oxygen consumption (mL/min), CaO2 = arterial O2 content (mL/100mL), CvO2 = mixed venous O2 content (mL/100mL)."]','A','Normal values: VO2 ~250 mL/min; CaO2 ~20 mL/100mL; CvO2 ~15 mL/100mL; a-v O2 diff = 5 mL/100mL; CO = 250/50 = 5 L/min. Wide a-v O2 difference = low CO (more O2 extracted per unit blood). Alternative: thermodilution (Swan-Ganz catheter).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','medium','flashcard','What are the three determinants of stroke volume?','["1. Preload (EDV - Frank-Starling) 2. Afterload (SVR/aortic impedance - opposes ejection) 3. Contractility (inotropy - intrinsic myocardial force at given preload/afterload)"]','A','Preload increases: SV increases (Starling). Afterload increases: SV decreases (harder to eject). Contractility increases: SV increases (shifts Starling curve up). All three are independent variables. CO = HR x SV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','easy','flashcard','What is normal cardiac output and cardiac index at rest?','["Normal CO \u2248 5 L/min (range 4-8 L/min). Normal cardiac index (CI = CO/BSA) \u2248 2.5-4.0 L/min/m2."]','A','Cardiogenic shock criterion: CI <2.2 L/min/m2. CO increases to 20-25 L/min during maximal exercise in athletes. The cardiac reserve (difference between maximal and resting CO) is reduced in heart failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','medium','flashcard','What is the Bowditch (Treppe) effect and how does it differ from Frank-Starling?','["Bowditch/Treppe: as heart rate increases, contractile force increases step-by-step due to accumulation of intracellular Ca2+ (frequency-force relationship). Frank-Starling: at fixed HR, increased preload (EDV) increases SV via sarcomere length-tension relationship."]','A','Bowditch = frequency-dependent inotropy. Frank-Starling = length-dependent inotropy. Both enhance SV/CO during exercise. Bowditch is why digoxin (which also raises [Ca2+]i) is not the only way to increase force - simply increasing HR helps too.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','hard','flashcard','On a Frank-Starling diagram, how does sympathetic stimulation change the cardiac function curve?','["Sympathetic stimulation shifts the Starling curve UPWARD and to the LEFT - at any given preload (EDV), SV and CO are greater. This reflects increased contractility (positive inotropy)."]','A','Conversely, heart failure/negative inotropes shift the curve downward/right. On a Guyton diagram (CO vs. RAP), sympathetic stimulation shifts the cardiac function curve upward AND the venous return curve rightward (venoconstriction increases Psf), moving the equilibrium point to higher CO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','medium','flashcard','Define afterload and give two clinical conditions that increase it.','["Afterload = the load against which the ventricle contracts during ejection = wall tension during systole. Clinically: LV afterload \u2248 SVR and aortic impedance."]','A','Conditions increasing afterload: (1) Systemic hypertension (increased SVR); (2) Aortic stenosis (fixed obstruction at valve level). Both increase LV wall stress, impair ejection, and cause concentric hypertrophy. Vasodilators (ACE inhibitors, ARBs, hydralazine) reduce afterload and improve SV in heart failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','hard','flashcard','What happens to cardiac output in high-output states (e.g., severe anaemia, pregnancy, AV fistula)?','["CO is elevated (high-output) due to reduced SVR/afterload and/or increased venous return (preload). Despite high CO, MAP may remain normal (CO x SVR = MAP). The heart compensates with eccentric hypertrophy if sustained."]','A','In severe anaemia: reduced O2 delivery despite high CO, reduced viscosity lowers SVR, sympathetic activation increases HR and CO. In AV fistula: low-resistance shunt increases venous return and CO. Heart failure can eventually develop ("high-output heart failure").','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','medium','flashcard','What is the formula for stroke work (SW) and what does it represent?','["Stroke work (SW) = Stroke Volume x Mean Arterial Pressure (or more precisely, area enclosed by the PV loop). Units: mmHg x mL = gram-metres."]','A','SW represents the external work done by the ventricle per beat. At high afterload (high MAP), SW increases even if SV decreases - this is metabolically costly. SW index = SW / BSA. The heart also does internal work (isovolumetric contraction) which contributes to myocardial O2 demand.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Output & Starling''s Law','easy','flashcard','How does cardiac output change during maximal aerobic exercise?','["CO increases 4- to 7-fold (from ~5 L/min to 20-35 L/min in trained athletes) due to increased HR (up to 180-200 bpm), increased SV (Frank-Starling + sympathetic inotropy), and dramatically reduced SVR in active muscles."]','A','Untrained adults: CO max ~15-20 L/min. Elite athletes: up to 35-40 L/min. The increase in SV during exercise (up to 150-200 mL) occurs mainly from reduced ESV (stronger contraction) rather than increased EDV. VO2 max is limited by CO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','easy','flashcard','What are the intrinsic firing rates of the SA node, AV node, and ventricular Purkinje fibres?','["SA node: 60-100 bpm. AV node: 40-60 bpm. Ventricular Purkinje fibres: 20-40 bpm."]','A','The SA node has the highest intrinsic rate and therefore acts as the dominant pacemaker (overdrive suppression). If the SA node fails, the AV node takes over as a junctional escape rhythm. If AV block occurs, an idioventricular rhythm at 20-40 bpm is the escape. All escape rhythms are slower than normal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','medium','flashcard','What is the If (funny) current and which drug selectively blocks it?','["If is a hyperpolarisation-activated inward Na+/K+ current (HCN channels) that drives the slow phase 4 depolarisation (pacemaker potential) in the SA node. Ivabradine selectively blocks If, slowing heart rate without affecting contractility."]','A','If is activated at negative membrane potentials (< -40 to -60 mV) and deactivated by depolarisation. Sympathetic stimulation (cAMP) increases If slope (tachycardia); vagal stimulation (ACh/Gi) decreases it (bradycardia). Ivabradine: used in stable angina and heart failure (preserved EF component).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','medium','flashcard','What is the mechanism by which muscarinic M2 receptor activation slows the heart?','["Vagal ACh activates M2 receptors (Gi-coupled) on SA node: Gi inhibits adenylyl cyclase (reducing cAMP) and directly opens IKACh channels. K+ efflux hyperpolarises the SA node cell and reduces slope of phase 4, slowing firing rate."]','A','Atropine blocks M2 receptors, removing vagal brake, causing tachycardia. Used clinically in: sinus bradycardia, AV block (temporarily), organophosphate poisoning. The SA node is under constant vagal tone at rest, so resting HR (60-70 bpm) is below the intrinsic SA rate (~100 bpm).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','medium','flashcard','How does beta-1 adrenoceptor stimulation increase heart rate (the mechanism)?','["Beta-1 activation (Gs-cAMP-PKA) increases If (steeper phase 4 slope), increases ICa,L (faster SA node upstroke), and shifts threshold voltage more negative - all causing the SA node to reach threshold faster and fire more rapidly (positive chronotropy)."]','A','Same PKA also phosphorylates: troponin I (faster relaxation - lusitropy), phospholamban (faster Ca2+ reuptake by SERCA), L-type Ca2+ channels (increased force). This is why beta-blockers slow HR AND reduce contractility. Beta-1 selectivity: atenolol, metoprolol, bisoprolol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','easy','flashcard','What is the baroreflex and how does it respond to a sudden drop in blood pressure?','["Baroreflex: baroreceptors (carotid sinus, aortic arch) detect pressure fall, reduce afferent firing to NTS (medulla), decrease vagal outflow and increase sympathetic outflow = increased HR, vasoconstriction, increased contractility, restoring BP."]','A','Baroreflex acts within seconds. Set-point resets in chronic hypertension (baroreceptors recalibrate). Baroreflex sensitivity (BRS) is reduced in heart failure and hypertension. Carotid sinus hypersensitivity can cause syncope. Baroreflex failure = severe labile hypertension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','hard','flashcard','What is the Bainbridge reflex and what causes it?','["Bainbridge reflex: increased right atrial pressure (from increased venous return) stimulates atrial stretch receptors, which via vagal afferents to the medulla causes reflex tachycardia (increased HR to handle the increased venous return)."]','A','The Bainbridge reflex complements Frank-Starling: Frank-Starling increases SV in response to more filling; Bainbridge increases HR. Together they increase CO to match venous return. At high HR (when Bainbridge reflex competes with baroreflex), the net effect on HR depends on baseline.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','medium','flashcard','Name four physiological factors that increase heart rate (positive chronotropy).','["1. Sympathetic stimulation (noradrenaline, adrenaline via beta-1) 2. Decreased parasympathetic tone 3. Fever (increases metabolic rate, Q10 effect) 4. Thyroid hormone (increases beta-1 receptor density and sensitivity)"]','A','Also: exercise (sympathetic + vagal withdrawal), hypoxia (via chemoreceptors), hypercapnia, stretch of SA node (Bainbridge). Beta-blockers are negative chronotropes. Parasympathomimetics (digoxin, neostigmine) slow HR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','easy','flashcard','Where is the cardiovascular centre located and what are its two main components?','["Located in the medulla oblongata (reticular formation). Two components: (1) Vasomotor centre (ventrolateral medulla) - controls sympathetic vascular tone; (2) Cardiac centre - includes cardioacceleration (sympathetic) and cardioinhibitory (vagal/parasympathetic) areas."]','A','Higher centres (hypothalamus, cortex, amygdala) modulate the medullary centres - e.g., emotional stress (cortex/amygdala) causes tachycardia. NTS (nucleus tractus solitarius) receives baroreceptor and chemoreceptor afferents. CNS ischaemia (Cushing reflex) causes severe bradycardia via vagus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','hard','flashcard','What is heart rate variability (HRV) and what does high HRV indicate?','["HRV = beat-to-beat variation in RR intervals on ECG. High HRV indicates strong parasympathetic (vagal) modulation, which is a marker of cardiovascular health, autonomic flexibility, and fitness."]','A','Low HRV: heart failure, post-MI, diabetes (autonomic neuropathy), ageing, stress, depression. HRV is assessed by time-domain (SDNN, RMSSD) and frequency-domain (HF = parasympathetic, LF = sympathetic/parasympathetic). Used in risk stratification post-MI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Heart Rate Regulation','medium','flashcard','What is "overdrive suppression" in the context of cardiac pacemakers?','["Overdrive suppression: the faster SA node continuously stimulates slower pacemaker cells (AV node, Purkinje fibres) before they can spontaneously depolarise. When the SA node fails, there is a brief asystole before a subsidiary pacemaker escapes (latent pacemakers are suppressed)."]','A','Clinically important: after cardioversion of long-standing atrial fibrillation, the SA node (suppressed by AF) may take several seconds to restart - "sick sinus syndrome." Ectopic pacemakers (e.g., VT) also suppress the normal SA node via overdrive suppression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','easy','flashcard','What is the formula for mean arterial pressure (MAP) and what does it represent physiologically?','["MAP = DBP + 1/3(SBP - DBP) = DBP + 1/3 PP. MAP represents the average driving pressure for organ perfusion over the cardiac cycle. Normal MAP \u2248 70-100 mmHg."]','A','Derived from MAP = CO x SVR. The 1/3 factor reflects that diastole occupies 2/3 of the cycle at rest. Target MAP in septic shock: ≥65 mmHg. MAP below 60 mmHg = inadequate perfusion pressure for vital organs (especially brain, coronary). Cerebral perfusion pressure (CPP) = MAP - ICP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','medium','flashcard','What is pulse pressure and in which conditions is it widened vs. narrowed?','["Pulse pressure = SBP - DBP. Normal ~40 mmHg. Widened PP (>60 mmHg): aortic regurgitation, PDA, AV fistula, thyrotoxicosis, aortic stiffness, fever. Narrowed PP (<25 mmHg): cardiac tamponade, haemorrhagic shock, severe aortic stenosis, heart failure."]','A','Widened PP in aortic regurgitation: high SBP (large SV) + low DBP (diastolic run-off through incompetent valve). Narrow PP in tamponade: cardiac compression reduces stroke volume (low SBP) while venous pressure is high (high DBP). Pulsus paradoxus: PP narrows further on inspiration in tamponade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','easy','flashcard','State the relationship between MAP, cardiac output, and systemic vascular resistance.','["MAP = CO x SVR (where SVR = systemic vascular resistance). This is the hydraulic equivalent of Ohm''s law (V = IR). SVR = (MAP - CVP) / CO x 80 (in dyne\u00b7s/cm5)."]','A','This formula is the foundation of haemodynamic management. In septic shock: low SVR causes low MAP despite high CO. In cardiogenic shock: low CO causes low MAP despite elevated SVR. In hypertension: usually elevated SVR (unless high-output, as in pregnancy or anaemia).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','medium','flashcard','What is the Windkessel effect and how does it change with ageing?','["Windkessel effect: the elastic aorta and large arteries distend during systole (storing kinetic energy), then recoil during diastole (sustaining diastolic pressure and maintaining continuous flow). With ageing/arteriosclerosis: aortic compliance falls, Windkessel effect diminishes."]','A','Consequences of reduced Windkessel effect: (1) SBP rises (blood ejected into stiff vessel, no buffering); (2) DBP falls (less diastolic recoil); (3) Pulse pressure widens; (4) Isolated systolic hypertension; (5) Increased cardiac afterload; (6) Increased risk of coronary ischaemia (coronary flow depends on diastolic pressure).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','hard','flashcard','What is the autoregulatory range for cerebral blood flow and what happens outside it?','["Cerebral autoregulation: constant CBF maintained over MAP of approximately 60-150 mmHg. Below 60 mmHg: cerebral ischaemia (vasodilation maxed out). Above 150 mmHg: forced pressure breakthrough, endothelial damage, hypertensive encephalopathy."]','A','In chronic hypertension: curve shifts rightward (CBF maintained at higher MAPs, but ischaemia risk increases at "normal" MAPs). In SAH/TBI: autoregulation impaired, CBF passively follows MAP. CPP = MAP - ICP; target CPP >60 mmHg in TBI management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','medium','flashcard','How do baroreceptors regulate blood pressure in the short term?','["Baroreceptors in the carotid sinus and aortic arch are stretch receptors that increase firing with rising BP. Increased baroreceptor activity \u2192 increased NTS activity \u2192 increased vagal outflow (slows HR, reduces contractility) + decreased sympathetic outflow (vasodilation, decreased HR). Net effect: BP falls back to set-point."]','A','Baroreceptors reset to any new sustained pressure level within hours-days (explains why they do not control long-term BP). Carotid sinus massage: increases baroreceptor firing → vagal surge → can terminate SVT, slow ventricular rate in AF. Carotid sinus hypersensitivity: exaggerated vagal response causing syncope.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','easy','flashcard','Explain Poiseuille''s law and its clinical relevance to vascular resistance.','["R = 8nL / pr4. Resistance (R) is proportional to viscosity (n) and length (L), but inversely proportional to the FOURTH power of radius (r). Doubling radius reduces resistance 16-fold; halving radius increases resistance 16-fold."]','A','Clinical relevance: (1) Arterioles can regulate flow dramatically with small radius changes; (2) IV cannula size matters hugely - a 14G (large) cannula can infuse 16x faster than a 16G (half the radius) for the same pressure; (3) Vasoconstriction (reduced radius) dramatically increases SVR even with small diameter change.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','medium','flashcard','What is the RAAS and why is it the primary long-term regulator of blood pressure?','["Renin-angiotensin-aldosterone system: renal juxtaglomerular cells release renin \u2192 cleaves angiotensinogen to Ang I \u2192 ACE converts Ang I to Ang II \u2192 Ang II: vasoconstriction (raises SVR), aldosterone release (Na+ retention, raises volume), ADH release, thirst. Net effect: raises BP via both volume and resistance."]','A','The kidney is the primary long-term BP regulator because only the kidney can create sustained Na+/water retention (raising circulating volume). Baroreceptors reset within 1-3 days. RAAS inhibitors (ACE inhibitors, ARBs, aldosterone antagonists) are first-line antihypertensives. Hyperaldosteronism (Conn syndrome) causes hypertension + hypokalaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','hard','flashcard','What is pressure natriuresis and how does it relate to long-term BP control?','["Pressure natriuresis: as renal perfusion pressure (MAP) rises, the kidney excretes more Na+ and water (natriuresis and diuresis), reducing blood volume and cardiac preload, ultimately lowering CO and MAP. This creates an infinitely sensitive feedback loop for long-term BP."]','A','Guyton''s concept: the operating point where renal output = intake determines long-term MAP. If renal Na+ excretion curve shifts (e.g., increased aldosterone, renal artery stenosis), MAP rises to restore balance (essential hypertension). The kidney has infinite gain for long-term pressure control - eventually BP will stabilise at the level where renal Na+ output = intake.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Arterial Blood Pressure & Mean Arterial Pressure','medium','flashcard','What is isolated systolic hypertension and what causes it in the elderly?','["Isolated systolic hypertension (ISH): SBP \u2265140 mmHg with DBP <90 mmHg. Most common form of hypertension in adults over 60. Caused by reduced aortic compliance (arteriosclerosis) impairing the Windkessel effect."]','A','Pathophysiology: stiff aorta cannot buffer the stroke volume during systole, so SBP rises. Diastolic pressure may fall because there is less elastic recoil maintaining DBP. Wide pulse pressure is characteristic. ISH is a major risk factor for stroke, CAD, and heart failure. Treated similarly to other hypertension (CCBs, diuretics, ACE inhibitors).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','easy','flashcard','State the four Starling forces and their directions at the arterial end of a capillary.','["At arterial end (promoting filtration OUT): capillary hydrostatic pressure (Pc \u2248 35 mmHg) > plasma oncotic pressure (pc \u2248 28 mmHg) \u2192 net filtration outward. Interstitial hydrostatic pressure (Pi \u2248 -3 mmHg) and interstitial oncotic pressure (pi \u2248 8 mmHg) are minor modifiers."]','A','Net filtration pressure at arterial end ≈ +13 mmHg (outward). At venous end, Pc falls to ~15 mmHg, net pressure ≈ -7 mmHg (inward reabsorption). Lymphatics drain the ~3 litres/day that is not reabsorbed. Oedema = when filtration exceeds reabsorption + lymphatic drainage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','medium','flashcard','What is plasma oncotic (colloid osmotic) pressure, what generates it, and what is the normal value?','["Plasma oncotic pressure \u2248 28 mmHg; generated primarily by albumin (60-80% of oncotic pressure) and to lesser extent globulins and fibrinogen. It opposes capillary filtration and promotes reabsorption at the venous end."]','A','In hypoalbuminaemia (albumin <25 g/L): oncotic pressure falls, net capillary filtration exceeds reabsorption → oedema. Causes: nephrotic syndrome (protein loss in urine), liver failure (reduced albumin synthesis), malnutrition/kwashiorkor, protein-losing enteropathy. Intravenous albumin administration can temporarily restore oncotic pressure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','easy','flashcard','What is the primary mechanism of capillary solute exchange?','["Diffusion - passive movement down concentration gradients. Lipid-soluble substances (O2, CO2, steroids, most drugs) diffuse through endothelial cell membranes. Water-soluble substances (glucose, ions, amino acids) diffuse through intercellular clefts (~6-7 nm wide)."]','A','Fick''s law: diffusion rate = Diffusion coefficient x Surface area x Concentration gradient / Distance. The enormous capillary surface area (500-700 m2 in humans) and very short diffusion distances (<50 µm to any cell) make diffusion highly efficient. Large proteins cannot diffuse through endothelial clefts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','medium','flashcard','What is vasomotion and what regulates it?','["Vasomotion = rhythmic contraction/relaxation of precapillary sphincters, causing intermittent (rather than continuous) capillary blood flow. Regulated by local tissue O2 tension: low O2 \u2192 sphincters relax \u2192 more capillaries open; high O2 \u2192 sphincters contract."]','A','Vasomotion is a form of local metabolic autoregulation. It allows fine-tuning of capillary surface area and functional capillary density to match tissue metabolic needs without requiring neural input. During exercise, active muscle capillary density increases 10-100x via vasomotion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','hard','flashcard','Name the three types of capillary structure and where each is found.','["1. Continuous (tight junctions, smallest pores): brain (blood-brain barrier), skeletal muscle, cardiac muscle, lung. 2. Fenestrated (60-80 nm pores): kidney glomeruli, intestinal villi, endocrine glands. 3. Sinusoidal/discontinuous (large gaps, no basal lamina): liver, spleen, bone marrow."]','A','Blood-brain barrier: continuous capillaries with very tight junctions and astrocyte foot processes; limits passage of many drugs (reason CNS drugs must be lipophilic). Glomerular fenestrations facilitate filtration but remain selective by charge (anionic barrier) and size. Liver sinusoids allow passage of large proteins (albumin synthesis and secretion).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','medium','flashcard','What causes oedema in each of these four mechanisms: increased hydrostatic pressure, decreased oncotic pressure, increased capillary permeability, and lymphatic obstruction?','["1. Increased Pc (heart failure, venous obstruction): more filtration, cannot be reabsorbed. 2. Decreased pc (hypoalbuminaemia): less reabsorption at venous end. 3. Increased permeability (inflammation, sepsis, burns): protein leaks out, raising pi. 4. Lymphatic obstruction (filariasis, post-mastectomy, malignancy): filtrate accumulates (lymphoedema)."]','A','Clinical: DVT → venous hypertension → pitting oedema in leg (increased Pc). Nephrotic syndrome → hypoalbuminaemia → bilateral pitting oedema (decreased pc). Anaphylaxis → histamine increases permeability → angioedema (increased permeability). Breast cancer surgery → lymphoedema in arm (lymphatic obstruction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','easy','flashcard','What is reactive hyperaemia and what mediators cause it?','["Reactive hyperaemia = increased blood flow following a period of ischaemic occlusion, caused by accumulation of local vasodilator metabolites: adenosine, CO2, H+ (acidosis), K+, prostaglandins, and depletion of O2."]','A','Duration and magnitude of reactive hyperaemia is proportional to duration of occlusion (more metabolite accumulation). This is the physiological basis of coronary reserve assessment (pharmacological stress tests use adenosine to mimic exercise-induced vasodilation in stenosed vessels).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','medium','flashcard','What is the lymphatic capillary pump and how does lymph return to the circulation?','["Lymphatic capillaries are blind-ended, have one-way valves and anchoring filaments. Lymph flows (driven by: lymphangion smooth muscle contraction, skeletal muscle pump, respiratory pump, intestinal peristalsis) through lymph nodes into the thoracic duct \u2192 left subclavian vein, and right lymphatic duct \u2192 right subclavian vein."]','A','The thoracic duct drains the entire body except the right upper quadrant (which drains into the right lymphatic duct). Normal lymph flow ≈ 2-4 litres/day. Filariasis (Wuchereria bancrofti infection) obstructs lymphatics → massive lymphoedema (elephantiasis). All protein that filters into the interstitium must be returned by the lymphatics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','hard','flashcard','What is autoregulation of blood flow and what are the two main mechanisms?','["Autoregulation = the ability of an organ to maintain constant blood flow despite changes in perfusion pressure. Mechanisms: (1) Myogenic: smooth muscle contracts when stretched by increased pressure; (2) Metabolic: fall in O2/rise in vasodilator metabolites causes vasodilation to restore flow."]','A','Organs with strong autoregulation: brain (MAP 60-150), kidney (MAP 80-170), heart. Organs with poor autoregulation: skin, splanchnic. Metabolic autoregulation dominates in heart, brain, and skeletal muscle during exercise. Myogenic autoregulation is prominent in the kidney (protecting glomerulus from pressure changes). Failed autoregulation underlies many disease states.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Microcirculation & Capillary Exchange','medium','flashcard','What is the arteriole and why is it the key site of vascular resistance control?','["Arterioles are small resistance vessels (diameter 10-100 \u00b5m) with a thick smooth muscle wall that can vary radius greatly. Because resistance \u221d 1/r4 (Poiseuille), even small changes in arteriolar radius cause enormous changes in resistance and therefore flow distribution."]','A','Arterioles account for approximately 50% of total peripheral resistance. Controlled by: local metabolic factors (dominant), sympathetic innervation (alpha-1 receptors: constrict; beta-2: dilate in muscle), hormones (Ang II, vasopressin: constrict; NO, ANP: dilate). Arteriolar tone determines both blood pressure and blood flow distribution.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','easy','flashcard','What is the normal central venous pressure (CVP) range and what does it reflect?','["Normal CVP: 0-8 mmHg (0-10 cmH2O). CVP reflects right atrial pressure and provides an indirect estimate of right ventricular preload. It is measured at the level of the right atrium (4th intercostal space, mid-axillary line)."]','A','Elevated CVP (>12 mmHg): right heart failure, cardiac tamponade, tension pneumothorax, fluid overload, PEEP. Low CVP (<2 mmHg): hypovolaemia, dehydration, haemorrhage. CVP is an imperfect estimate of volume status (affected by cardiac compliance, tricuspid disease). Fluid responsiveness is now assessed by dynamic indices (pulse pressure variation).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','medium','flashcard','What is mean systemic filling pressure (Psf) and how does it relate to venous return?','["Psf (approximately 7 mmHg in humans) is the equilibration pressure throughout the systemic vasculature when the heart stops. It reflects total blood volume relative to total vascular compliance. The gradient driving venous return = Psf - right atrial pressure (RAP)."]','A','Increasing Psf (fluid loading, sympathetic venoconstriction): increases VR gradient, increases venous return and CO. Decreasing RAP (more negative - deep inspiration): increases VR gradient. This is the basis of Guyton''s venous return curve. VR is also reduced by increased resistance to venous return (e.g., abdominal compartment syndrome).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','easy','flashcard','What is the venous (skeletal muscle) pump and why does it fail in varicose veins?','["Venous pump: skeletal muscle compression propels blood toward the heart; one-way venous valves prevent backflow during muscle relaxation. Pumps approximately 750 mL/min from the legs during walking."]','A','Varicose veins: incompetent valves allow retrograde flow during muscle relaxation → venous hypertension → chronic venous insufficiency, lipodermatosclerosis, venous ulcers. Treatment: compression stockings (augment muscle pump), surgical stripping, sclerotherapy, endovenous ablation. DVT can also destroy valve function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','medium','flashcard','How does inspiration enhance venous return (the respiratory pump)?','["During inspiration, the diaphragm descends, intrathoracic (pleural) pressure falls (becomes more negative, typically -4 to -8 mmHg). This: (1) expands thoracic veins and right atrium, increasing venous return; (2) reduces right ventricular afterload (expanding pulmonary bed). The reverse occurs during expiration."]','A','Pulsus paradoxus: exaggerated fall in systolic BP (>10 mmHg) on inspiration in cardiac tamponade (fluid compresses heart, preventing RV expansion during inspiration → SV falls → BP falls). Kussmaul''s sign: JVP RISES on inspiration (constrictive pericarditis - rigid pericardium prevents RV from accommodating the increased VR).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','hard','flashcard','What is orthostatic (postural) hypotension and what are its causes?','["Orthostatic hypotension: drop in systolic BP \u226520 mmHg or diastolic BP \u226510 mmHg within 3 minutes of standing. On standing, 500-700 mL pools in lower limb veins, reducing venous return, SV, CO, and MAP. Normally, the baroreflex compensates within seconds."]','A','Causes of impaired compensation: (1) Autonomic neuropathy (diabetes, Parkinson''s, MSA); (2) Hypovolaemia; (3) Drugs: vasodilators, diuretics, beta-blockers, alpha-blockers, TCA; (4) Prolonged bed rest/deconditioning; (5) Age-related baroreflex impairment. Treatment: compression stockings, fludrocortisone (volume expansion), midodrine (alpha-agonist).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','medium','flashcard','What percentage of total blood volume resides in the venous system and what is the clinical significance?','["Approximately 60-70% of total blood volume resides in the veins (venous capacitance vessels). The remaining: arteries ~15%, capillaries ~5%, heart and lungs ~20%."]','A','Clinical significance: the venous system is the primary blood reservoir. Sympathetic venoconstriction can rapidly mobilise 500-1000 mL from this reservoir into the central circulation, increasing venous return and CO (autotransfusion effect). In haemorrhagic shock, venoconstriction is an early compensatory mechanism. Vasodilators can cause venous pooling and reduced preload (nitrates work primarily as venodilators).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','easy','flashcard','What are the JVP waveform components and what physiological event does each represent?','["a wave = atrial contraction. c wave = tricuspid valve closure (and transmitted aortic pulsation). x descent = atrial relaxation + downward displacement of tricuspid valve. v wave = venous filling of atrium during systole (against closed tricuspid). y descent = tricuspid valve opens, rapid ventricular filling."]','A','Absent a wave: AF (no coordinated atrial contraction). Large a wave: pulmonary hypertension, PS, TS (atrium pumping against resistance). Cannon a wave: AV dissociation (complete heart block, VT). Large v wave: tricuspid regurgitation (regurgitant blood pulsates back into the vein during systole). Absent x descent: TR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','hard','flashcard','On the Guyton diagram (CO/VR curve), what happens when you administer a positive inotrope?','["Positive inotrope shifts the cardiac function curve upward (higher CO at any given RAP). If venous return curve is unchanged, the operating point moves to higher CO and lower RAP (the heart empties more effectively, lowering filling pressure). Ultimately, new equilibrium at higher CO."]','A','If sympathetic stimulation also increases venous tone (raises Psf), the venous return curve shifts rightward simultaneously. The combined effect (new equilibrium) is the largest CO increase. This is why dobutamine (positive inotrope) + noradrenaline (vasopressor/venoconstrictor) together can more effectively increase CO than either alone in cardiogenic shock.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','medium','flashcard','What is Kussmaul''s sign and in which conditions is it found?','["Kussmaul''s sign = paradoxical RISE in JVP on inspiration (normally JVP falls on inspiration). Found in: constrictive pericarditis, cardiac tamponade (less reliable), right ventricular infarction, restrictive cardiomyopathy, severe right heart failure."]','A','Mechanism: the rigid pericardium (constrictive) or fluid (tamponade) prevents the RV from expanding to accommodate the increased venous return during inspiration; blood backs up in the systemic veins, raising JVP. The absence of Kussmaul''s sign in tamponade (where pulsus paradoxus is present instead) reflects the different hemodynamics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Venous Return & Venous Pressure','medium','flashcard','How does positive pressure mechanical ventilation affect venous return and cardiac output?','["Positive pressure ventilation (PPV) increases intrathoracic pressure during inspiration. This compresses the intrathoracic veins and right atrium, reducing the pressure gradient for venous return (Psf - RAP gradient decreases). This reduces venous return, RV filling, and cardiac output."]','A','Clinical implications: PEEP (positive end-expiratory pressure) can cause significant haemodynamic compromise, especially in hypovolaemic patients. Fluid loading counteracts this by raising Psf. PPV can also cause right heart failure if pulmonary vascular resistance increases with high PEEP. Pulsus paradoxus is exaggerated with PPV in tamponade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','easy','flashcard','Name the territories supplied by the three main coronary arteries.','["LAD (left anterior descending): anterior LV wall, anterior 2/3 of interventricular septum, apex. LCx (left circumflex): lateral and posterior LV wall, left atrium. RCA (right coronary artery): right ventricle, SA node (60%), AV node (90%), posterior LV wall (in right-dominant circulation via PDA)."]','A','Left main coronary artery (LMCA) → LAD + LCx. LMCA disease is highest risk ("widow maker"). RCA occlusion → inferior STEMI (II, III, aVF elevation), often with heart block (AV node ischaemia) and right ventricular infarction. LAD occlusion → anterior STEMI (V1-V4), usually most extensive damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','medium','flashcard','When does left coronary blood flow occur predominantly and why?','["Left coronary flow is predominantly DIASTOLIC because during systole, high intramyocardial pressure compresses the left coronary vessels (especially subendocardium), severely reducing or even reversing flow. Diastole allows coronary vessels to decompress and fill."]','A','Clinical importance: at fast heart rates, diastolic time is short, reducing coronary perfusion time. This is why tachycardia (e.g., SVT, AF with rapid ventricular response) can precipitate angina. Diastolic BP is the main determinant of coronary perfusion pressure (DBP - LVEDP = coronary perfusion pressure). In contrast, right coronary flow occurs throughout the cardiac cycle because RV systolic pressure is low.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','easy','flashcard','What is the primary local regulator of coronary blood flow?','["Myocardial metabolism (metabolic autoregulation). The primary mediator is adenosine, released when ATP is broken down during increased cardiac work. Other mediators: CO2, H+, K+, prostaglandins, nitric oxide."]','A','Adenosine is the most important coronary vasodilator. It acts on A2A receptors on coronary smooth muscle, increasing cAMP, causing vasodilation. Adenosine dipyridamole (inhibits adenosine reuptake) and regadenoson (A2A agonist) are used in pharmacological stress testing to maximally vasodilate coronary arteries and unmask stenoses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','hard','flashcard','What is coronary reserve and how is it assessed clinically?','["Coronary reserve = the ratio of maximal coronary blood flow (during hyperaemia) to resting coronary blood flow. Normal ratio \u2248 4-5x. In significant stenosis (>70%), autoregulatory vasodilation at rest maintains flow, but reserve is exhausted - ischaemia occurs with any increased demand."]','A','Clinical assessment: (1) Fractional flow reserve (FFR): ratio of distal-to-proximal coronary pressure during maximal vasodilation (adenosine infusion). FFR <0.80 = haemodynamically significant stenosis requiring revascularisation. (2) Coronary flow reserve (CFR) by Doppler wire. (3) Nuclear SPECT/PET imaging with adenosine or regadenoson.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','medium','flashcard','Why is the subendocardium most vulnerable to ischaemia?','["Subendocardium is most vulnerable because: (1) Highest wall stress \u2192 highest O2 demand; (2) Compressively occluded during systole \u2192 relies entirely on diastolic perfusion; (3) Farthest from epicardial coronary arteries \u2192 longest diffusion distance; (4) Cannot increase O2 extraction (already at ~75% extraction at rest)."]','A','When diastolic perfusion pressure falls (tachycardia, aortic regurgitation lowering DBP, or LVEDP rising in LV failure), subendocardial flow falls first. ECG changes: ST depression in subendocardial ischaemia (ST elevation = transmural ischaemia = STEMI). Subendocardial infarction = NSTEMI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','medium','flashcard','What is the mechanism of action of glyceryl trinitrate (GTN) in angina?','["GTN is an organic nitrate that is converted to nitric oxide (NO) in vascular smooth muscle. NO activates guanylyl cyclase \u2192 increases cGMP \u2192 activates PKG \u2192 reduces intracellular Ca2+ \u2192 vasodilation. Primarily venodilation (reduces preload) with some arteriolar dilation (reduces afterload)."]','A','GTN in angina works by: (1) Venodilation: reduces preload, lowers LVEDP, reduces wall stress and O2 demand; (2) Arteriolar dilation: reduces afterload; (3) Coronary artery dilation (including epicardial vessels), relieving vasospasm. Sublingual GTN works in 2-5 minutes. Tolerance develops with continuous use (nitrate tolerance; prevented by nitrate-free periods).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','easy','flashcard','What is the significance of coronary dominance?','["Coronary dominance refers to which artery gives rise to the posterior descending artery (PDA). Right dominant (70%): RCA gives PDA. Left dominant (10-15%): LCx gives PDA. Co-dominant (15%): both supply."]','A','Clinical significance: (1) Right dominant: RCA occlusion → inferior MI + AV node ischaemia (heart block); (2) Left dominant: LCx occlusion can cause inferior MI + AV block; (3) Knowing dominance helps predict complications and target vessel for revascularisation. CT coronary angiography or invasive angiography determines dominance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','medium','flashcard','What determines myocardial oxygen demand (MVO2)?','["Myocardial oxygen demand (MVO2) is primarily determined by: (1) Heart rate (HR) - most important; (2) Wall stress = (pressure x radius) / (2 x wall thickness) - related to preload and afterload; (3) Contractility. Product of HR x systolic BP (rate-pressure product) clinically estimates MVO2."]','A','This is why the "double product" (HR x SBP) is used to predict angina onset during exercise testing. Beta-blockers reduce all three components of MVO2 (reduce HR, contractility, and afterload). In severe aortic stenosis, both pressure afterload and LV hypertrophy (increased wall thickness) affect MVO2.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','hard','flashcard','What is the difference between angina, unstable angina, NSTEMI, and STEMI?','["Stable angina: reversible ischaemia with exertion, fixed stenosis, no plaque rupture. Unstable angina (UA): ischaemia at rest or minimal exertion, plaque disruption, no troponin rise. NSTEMI: plaque rupture with partial occlusion, troponin rise, ST depression/T inversion (subendocardial). STEMI: complete occlusion, transmural ischaemia, ST elevation, requires emergency revascularisation."]','A','UA and NSTEMI together = NSTE-ACS (treated similarly). STEMI requires primary PCI within 90 minutes (door-to-balloon time). Biomarkers: troponin rises in NSTEMI and STEMI (irreversible injury) but not in UA (no necrosis). The key differentiator between UA and NSTEMI is troponin elevation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Coronary Circulation','easy','flashcard','What is the normal resting coronary blood flow and how does the heart compare to other organs in oxygen extraction?','["Normal resting coronary blood flow \u2248 200-250 mL/min (4-5% of CO). The myocardium extracts approximately 70-75% of delivered O2 at rest (other organs extract only 25-30%). Therefore, increased O2 demand must be met almost entirely by INCREASING coronary flow (not extraction)."]','A','This near-maximal O2 extraction at rest means the heart has little O2 extraction reserve. Any increase in demand (exercise, tachycardia, hypertension) must be met by proportionate increase in coronary blood flow via metabolic vasodilation. This explains why even moderate coronary stenosis can cause ischaemia during exertion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','easy','flashcard','Describe the cardiac conduction sequence from SA node to ventricular muscle.','["SA node \u2192 Atrial myocardium (internodal tracts) \u2192 AV node (0.1 s delay) \u2192 Bundle of His \u2192 Left and right bundle branches \u2192 Purkinje fibres \u2192 Ventricular myocardium (endocardium to epicardium)."]','A','Conduction velocities: SA node 0.05 m/s (pacemaker), AV node 0.02-0.05 m/s (slowest - provides delay), Bundle of His 1-2 m/s, Purkinje fibres 1-4 m/s (fastest), Ventricular muscle 0.3-0.5 m/s. The ECG P wave = atrial depolarisation; PR interval = AV node delay; QRS = ventricular depolarisation; T wave = ventricular repolarisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','medium','flashcard','What does the PR interval on ECG represent and what is the normal range?','["PR interval = time from start of P wave (atrial depolarisation) to start of QRS (ventricular depolarisation). Normal: 0.12-0.20 s (3-5 small squares at 25 mm/s). It represents conduction through the atria and AV node delay."]','A','Short PR (<0.12 s): pre-excitation (WPW syndrome - accessory pathway bypasses AV node, delta wave). Prolonged PR (>0.20 s): first-degree heart block (slowed AV conduction, e.g., digoxin toxicity, inferior MI, myocarditis). Progressive PR prolongation + dropped beats: Wenckebach (Mobitz I). Fixed PR + dropped beats: Mobitz II.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','easy','flashcard','Why is the AV node delay physiologically important?','["AV node delay (~0.1 s) allows: (1) Atrial systole to complete before ventricular activation (atrial kick fills ventricle); (2) Rate-limiting function prevents very rapid atrial rates (e.g., atrial flutter 300 bpm) from driving ventricular rate too fast."]','A','AV nodal blocking drugs (beta-blockers, non-dihydropyridine CCBs, digoxin, adenosine) exploit this rate-limiting function for ventricular rate control in AF. AV node is the only normal conduction pathway between atria and ventricles (the fibrous AV ring electrically insulates them). If AV node is bypassed (WPW), rapid conduction during AF can cause VF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','medium','flashcard','What is the QRS complex on ECG and what does its duration indicate?','["QRS complex represents ventricular depolarisation (from endocardium to epicardium). Normal QRS duration: <0.12 s (3 small squares). Broad QRS (>0.12 s): bundle branch block, ventricular pacemaker, pre-excitation, hyperkalaemia, or ventricular ectopy."]','A','Normal narrow QRS = activation via the His-Purkinje system (rapid, synchronised). Broad QRS = either aberrant ventricular activation (slow cell-to-cell spread via myocardium, as in LBBB) or origin outside the conduction system (VT, ventricular pacemaker). The QRS axis (direction of activation vector) can diagnose hemiblocks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','medium','flashcard','What is the QT interval and what are the consequences of a prolonged QTc?','["QT interval = ventricular depolarisation + repolarisation (QRS + T wave duration). Normal corrected QTc: <440 ms (men), <460 ms (women). Prolonged QTc predisposes to torsades de pointes (TdP), a polymorphic VT that can degenerate into VF."]','A','QTc = QT / sqrt(RR interval) (Bazett formula). Prolonged QT causes: drugs (antiarrhythmics class IA/III, macrolides, quinolones, antipsychotics, methadone), electrolytes (low K+, Mg2+, Ca2+), congenital LQTS (channelopathies), hypothyroidism, hypothermia. TdP treatment: IV magnesium, correct electrolytes, remove causative drug, temporary pacing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','hard','flashcard','What is Wolff-Parkinson-White (WPW) syndrome and why is it dangerous in atrial fibrillation?','["WPW: an accessory pathway (Bundle of Kent) connects atria to ventricles, bypassing the AV node. ECG shows: short PR (<0.12 s), delta wave (slurred QRS upstroke), widened QRS. During AF, the accessory pathway can conduct impulses at very rapid rates (300+ bpm) \u2192 VF \u2192 cardiac arrest."]','A','Normal AV node limits ventricular rate in AF to ~150-180 bpm. But an accessory pathway has no decremental conduction (does not slow at fast rates), so AF can drive the ventricle at 300 bpm → VF. NEVER use AV nodal blockers (digoxin, verapamil, diltiazem, adenosine) in WPW + AF - they block the AV node but enhance accessory pathway conduction. Treatment: IV procainamide or cardioversion, then radiofrequency ablation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','medium','flashcard','What are the characteristics of left bundle branch block (LBBB) on ECG?','["LBBB (QRS >120 ms): broad notched M-shaped R waves in I, aVL, V5, V6; deep broad S waves in V1-V3; no septal Q waves in V5-V6; secondary ST-T changes (ST depression and T wave inversion opposite to QRS deflection)."]','A','New LBBB with chest pain = treat as STEMI equivalent (Sgarbossa criteria can help identify STEMI in LBBB). LBBB reverses normal septal activation (now right-to-left instead of left-to-right), eliminating normal septal Q waves. Causes: CAD (often LAD territory), hypertension, cardiomyopathy, aortic stenosis. RBBB often benign; LBBB usually indicates significant cardiac disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','easy','flashcard','What are the escape rates of: AV junctional rhythm and idioventricular rhythm?','["AV junctional (nodal) escape rhythm: 40-60 bpm (narrow QRS unless aberrant conduction). Idioventricular rhythm: 20-40 bpm (wide QRS, no preceding P wave)."]','A','In complete AV block: P waves and QRS complexes are completely independent. If a junctional escape (40-60 bpm): patient is less haemodynamically compromised. If only idioventricular escape (20-40 bpm): severely compromised, high risk of cardiac arrest. All require urgent pacing. Bridge therapy: atropine (if junctional), transcutaneous pacing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','hard','flashcard','What are the degrees of heart block and how does ECG differentiate them?','["1st degree: prolonged PR >200 ms, every P followed by QRS. 2nd degree Mobitz I (Wenckebach): progressively prolonging PR until a QRS is dropped (group beating). 2nd degree Mobitz II: fixed PR, intermittent dropped QRS (no warning). 3rd degree: complete AV dissociation, P and QRS completely independent."]','A','Mobitz I: usually at AV node level (narrow QRS escape), often benign (inferior MI, drugs). Mobitz II: infranodal (wide QRS), high risk of complete block - requires pacemaker. 3rd degree: always requires pacing. In inferior MI: AV block is usually Wenckebach (nodal), often transient. In anterior MI: AV block is often Mobitz II (infranodal), more serious.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Cardiac Conduction System','medium','flashcard','What is the difference between automaticity and conductivity in cardiac electrophysiology?','["Automaticity = ability of cardiac cells to spontaneously depolarise without external stimulation (property of pacemaker cells: SA node, AV node, Purkinje fibres). Conductivity = ability to propagate action potentials from cell to cell."]','A','Normal automaticity hierarchy: SA node (60-100 bpm) > AV node (40-60 bpm) > Purkinje/ventricle (20-40 bpm). Abnormal (enhanced) automaticity: an ectopic focus fires faster than the SA node (e.g., ectopic atrial tachycardia, accelerated junctional rhythm, accelerated idioventricular rhythm - can occur after MI). Re-entry (different from automaticity) is the most common mechanism of clinical arrhythmias.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','easy','flashcard','Name the three fetal shunts, their locations, and their postnatal remnants.','["1. Ductus venosus (umbilical vein \u2192 IVC, bypasses liver) \u2192 ligamentum venosum. 2. Foramen ovale (RA \u2192 LA, bypasses pulmonary circulation) \u2192 fossa ovalis. 3. Ductus arteriosus (pulmonary artery \u2192 aorta, bypasses lungs) \u2192 ligamentum arteriosum."]','A','Umbilical vein → ligamentum teres hepatis (visible on liver surface). Umbilical arteries → medial umbilical ligaments. Patent foramen ovale (PFO) persists in 25% of adults (flap valve fails to fuse) - potential paradoxical embolism source, associated with cryptogenic stroke.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','medium','flashcard','Why does fetal haemoglobin (HbF) have higher oxygen affinity than HbA and why is this important?','["HbF (alpha-2 gamma-2) binds 2,3-DPG less avidly than HbA (alpha-2 beta-2) because gamma chains lack the histidine residue that binds 2,3-DPG. Less 2,3-DPG binding = leftward shift of O2-dissociation curve = higher O2 affinity at placental PO2."]','A','At the placenta (PO2 ≈ 30-35 mmHg), maternal HbA releases O2 to fetal HbF, which has higher affinity and captures it. This is essential because placental gas exchange occurs at lower PO2 than pulmonary gas exchange. HbF is replaced by HbA by ~6 months of age. Conditions that shift curve rightward (acidosis, fever, 2,3-DPG) impair fetal oxygenation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','medium','flashcard','What is the ductus arteriosus and what keeps it open in fetal life vs. what closes it at birth?','["Ductus arteriosus: vascular connection between main pulmonary artery and descending aorta. OPEN in fetal life: maintained by prostaglandin E2 (PGE2) from the placenta and low O2 tension (O2 causes vasoconstriction in this vessel). CLOSES at birth: rising O2 tension + loss of placental PGE2 \u2192 ductal smooth muscle contracts."]','A','Functional closure within 24-72 hours. Anatomical closure (ligamentum arteriosum) within 2-3 weeks. PDA in premature infants: indomethacin (COX inhibitor, reduces PGE2) or ibuprofen closes it medically. Alprostadil (PGE1) keeps PDA open in duct-dependent congenital heart disease (e.g., pulmonary atresia, TGA). Surgical ligation if medical therapy fails.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','easy','flashcard','What is the foramen ovale and what happens to it at birth?','["Foramen ovale: flap valve opening in the interatrial septum (within the fossa ovalis) allowing blood to flow from RA to LA in the fetus (right-to-left, due to high right-sided pressures). At birth: LA pressure exceeds RA pressure (reversed gradient) \u2192 flap is pushed against the septum \u2192 functional closure."]','A','Anatomical closure (fusion) occurs within 1-2 years. Patent foramen ovale (PFO) persists in ~25% of adults - usually benign but can cause paradoxical embolism (thrombus from leg DVT passes from RA to LA → arterial embolism/stroke) during Valsalva (transient rise in RA pressure). PFO closure considered for cryptogenic stroke recurrence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','medium','flashcard','Describe the sequence of circulatory changes that occur at birth.','["1. First breath \u2192 alveoli expand \u2192 O2 rises \u2192 pulmonary vasoconstriction relieved \u2192 PVR falls 8-fold. 2. Cord clamped \u2192 placental low-resistance circuit removed \u2192 SVR rises. 3. LA pressure rises (more pulmonary return) > RA pressure \u2192 foramen ovale closes. 4. Rising O2 + falling PGE2 \u2192 ductus arteriosus contracts and closes."]','A','Net result: parallel fetal circulation (pulmonary and systemic in parallel, bypassed by shunts) converts to series adult circulation (pulmonary and systemic in series). Before birth: RV and LV pump in parallel. After birth: RV pumps to pulmonary, LV to systemic. Persistent fetal circulation (PPHN): failure of PVR to fall → continued right-to-left shunting through PFO/PDA → cyanosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','hard','flashcard','What is transposition of the great arteries (TGA) and how do fetal shunts maintain life?','["TGA: aorta arises from morphological right ventricle and pulmonary artery from morphological left ventricle. Creates two parallel circuits (deoxygenated blood circulates systemically; oxygenated blood circulates through pulmonary). Incompatible with life unless blood can mix via PFO, PDA, or VSD."]','A','Management: prostaglandin E1 (alprostadil) IV infusion to maintain PDA patency → allows some mixing; urgent balloon atrial septostomy (Rashkind procedure) via umbilical vein catheter → enlarges foramen ovale → better mixing. Definitive: arterial switch operation (Jatene procedure) in first 2 weeks of life (before LV involutes from low pulmonary pressure).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','medium','flashcard','What is tetralogy of Fallot (TOF) and what are its four components?','["TOF = four defects: 1. Ventricular septal defect (VSD - large, usually perimembranous). 2. Overriding aorta (aorta straddles VSD). 3. Right ventricular outflow tract obstruction (RVOTO/pulmonary stenosis). 4. Right ventricular hypertrophy (RVH - secondary to RVOTO)."]','A','Result: right-to-left shunt through VSD (deoxygenated blood enters aorta) → cyanosis. Severity depends on degree of RVOTO. "Tet spells": hypercyanotic episodes triggered by crying/feeding (increased O2 demand, decreased SVR) → increased R-to-L shunting. Treatment of spell: knee-chest position (increases SVR), oxygen, morphine, beta-blockers. Definitive: surgical repair.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','hard','flashcard','What is persistent pulmonary hypertension of the newborn (PPHN) and why does it cause cyanosis?','["PPHN: failure of pulmonary vascular resistance to fall after birth. High PVR \u2192 right-sided pressures remain high \u2192 blood continues to shunt right-to-left through PFO and PDA \u2192 deoxygenated blood enters systemic circulation \u2192 cyanosis."]','A','Causes: asphyxia, meconium aspiration syndrome, sepsis, congenital diaphragmatic hernia (lung hypoplasia → insufficient pulmonary vascular bed). Treatment: 100% O2 (pulmonary vasodilator), iNO (inhaled nitric oxide - selective pulmonary vasodilator), prostacyclin (PGI2), sildenafil (PDE5 inhibitor), ECMO if refractory. Key: high O2 normally causes pulmonary vasodilation (opposite of hypoxic pulmonary vasoconstriction).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','medium','flashcard','What is coarctation of the aorta and how does it present in a neonate vs. an adult?','["Coarctation of the aorta: narrowing of the descending aorta, typically at the insertion of the ligamentum arteriosum (juxtaductal). Neonate: severe, duct-dependent - presents with cardiovascular collapse when PDA closes (lower body perfused by ductus arteriosus); treat with PGE1 to reopen PDA. Adult/older child: hypertension in upper limbs, weak/absent femoral pulses, BP differential (arm > leg), rib notching on CXR (from intercostal collateral vessels)."]','A','Neonatal presentation: shock, acidosis, grey cyanosis of lower body (when PDA closes). Associated with bicuspid aortic valve (50-80% of cases) and Turner syndrome (45,XO). Definitive treatment: surgical repair or balloon angioplasty ± stenting.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Anatomy & Physiology','Fetal Circulation & Changes at Birth','easy','flashcard','What is the ductus venosus and why is it important in fetal circulation?','["Ductus venosus: fetal vessel connecting the umbilical vein to the IVC, allowing 50% of highly oxygenated placental blood to bypass the liver sinusoids and stream preferentially through the IVC and foramen ovale to the left heart and brain."]','A','The ductus venosus creates a preferential stream of well-oxygenated blood directly to the fossa ovalis (and hence to the left heart/coronary arteries/brain), while less-oxygenated blood from the SVC streams to the tricuspid valve and right ventricle (then to pulmonary artery/ductus arteriosus). This optimises O2 delivery to vital organs despite parallel circulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed');